with valid as (select id, store_id, sale_date, units, least(revenue, units) as least_revenue_units, round(units * 0.85, 2) as units_scaled from store_sales where sale_date >= date '2023-07-08'), scored as (select *, lead(units, 1) over (order by sale_date, id) as next_units, row_number() over (partition by store_id order by units_scaled, id) as seq_no, rank() over (partition by store_id order by units desc nulls first) as units_rank from valid), ranked as (select *, row_number() over (partition by store_id order by units nulls first, id) as rn from scored qualify rn = 1), metrics as (select id, store_id, units, least_revenue_units, units_scaled, seq_no, rn, min(units_scaled) over (partition by store_id) as store_id_min_units_scaled, ntile(5) over (partition by store_id order by next_units, id) as next_units_bucket, rank() over w_running as units_rank_2 from ranked window w_running as (partition by store_id order by units nulls last)), remaining_keys as (select id, store_id from metrics except distinct select id, store_id from store_sales where units > 29), reconciled as (select s.* from metrics s inner join remaining_keys k on s.id = k.id and s.store_id = k.store_id) select case when store_id_min_units_scaled >= 82 then 'HIGH' else 'LOW' end as store_id_min_units_scaled_tier, case when seq_no >= 7 then 'HIGH' else 'LOW' end as seq_no_tier, count(distinct id) as distinct_ids, stddev_samp(units) as units_stddev, percentile_approx(units_scaled, array(0.25, 0.5, 0.75)) as units_scaled_quartiles from reconciled group by grouping sets ((case when store_id_min_units_scaled >= 82 then 'HIGH' else 'LOW' end, case when seq_no >= 7 then 'HIGH' else 'LOW' end), (case when store_id_min_units_scaled >= 82 then 'HIGH' else 'LOW' end))
